insert into public.sources(id,title,url,rights,review_status) values ('e30-factory-repair-upload','BMW E30 Repair Manual','https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html','Private source scan; original archive linked','selected-pages-checked') on conflict(id) do nothing;
insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values ('e30-rear-lamp-bulb', 'electrical', 'Replace a rear lamp bulb', 'e30-factory-repair-upload', '63-7 · 1988-on rear lamp bulb access', array['M10', 'M20', 'M21', 'M40', 'M42', 'S14'], 'draft', '{"slug":"e30-rear-lamp-bulb","title":"Replace a rear lamp bulb","system":"electrical","engines":["M10","M20","M21","M40","M42","S14"],"level":"Beginner","kind":"replacement","duration":"15–25 min","durationBasis":"Estimate for access, replacement and a lamp check on the late coupe.","summary":"Reach the lamp carrier from inside the trunk and replace the bulb for the failed circuit.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late E30 325i coupe with the 1988-on rear lamp carrier. Check the actual lamp, build date and bulb markings. The early body, M3 and some convertibles use different assemblies.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"63-7 · 1988-on rear lamp bulb access","pdfPages":[1192]},"evidence":[{"label":"BMW 1991 325i coupe rear lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/rear_light.html"},{"label":"See the left rear lamp on the car","href":"/workshop?node=e30body%3Atail-light-left"},{"label":"BMW workshop manual download","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}],"tools":["Flashlight","Correct replacement bulb","Clean cloth","Helper for brake and reverse checks"],"cautions":["Park, set the parking brake and switch the lamps and ignition off before touching the holder.","Let the bulb cool. Avoid forcing the carrier or fitting a different wattage."],"steps":[{"title":"Identify the circuit that failed","body":"Compare the two sides with the parking lights, hazards and brake lamps operated separately. If testing the reverse lights, secure the car and have a helper observe with the engine off.","check":"You know which function and side have failed."},{"title":"Release the trunk-side cover","body":"Open the trunk and turn the fastener on the cover behind the affected lens. Lift out the cover and expose the bulb carrier. Compare the installed layout with the rear lamp diagram.","check":"The carrier is accessible without levering the exterior lens."},{"title":"Match and replace the bulb","body":"Remove the bulb from the affected socket. Match the wattage, base and contact arrangement to the original and the catalog. Check that the contacts and carrier are clean, dry and intact. Fit the matching bulb and refit the cover.","check":"The bulb seats securely and the cover fastens without force."},{"title":"Test every function on that side","body":"Switch the circuits on one at a time with a helper. If a lamp still fails or the carrier is damaged, check the matching wiring diagram and connector before replacing anything else.","check":"The repaired lamp, its neighboring lamps and any check-control warning behave normally."}],"jobSupport":{"reviewedOn":"2026-11-11","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Bulb with the wattage, base and contacts listed for the fitted lamp"],"conditionalParts":["Bulb carrier or gasket if the housing shows damage or water entry"],"stopConditions":["The socket is melted, heavily corroded or wet.","The replacement base or contacts differ from the fitted bulb."],"steps":[{"number":1,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":["Flashlight"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":["Matching bulb","Clean cloth"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":4,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]}}'::jsonb) on conflict(id) do nothing;
insert into public.guide_revision_archive(guide_id,revision,content) values ('e30-rear-lamp-bulb', 'd16a7e54d3c9409c938c8afa', '{"slug":"e30-rear-lamp-bulb","title":"Replace a rear lamp bulb","system":"electrical","engines":["M10","M20","M21","M40","M42","S14"],"level":"Beginner","kind":"replacement","duration":"15–25 min","durationBasis":"Estimate for access, replacement and a lamp check on the late coupe.","summary":"Reach the lamp carrier from inside the trunk and replace the bulb for the failed circuit.","reviewStatus":"draft","sourceChecked":true,"applicability":"Late E30 325i coupe with the 1988-on rear lamp carrier. Check the actual lamp, build date and bulb markings. The early body, M3 and some convertibles use different assemblies.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"63-7 · 1988-on rear lamp bulb access","pdfPages":[1192]},"evidence":[{"label":"BMW 1991 325i coupe rear lamp diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/lighting/rear_light.html"},{"label":"See the left rear lamp on the car","href":"/workshop?node=e30body%3Atail-light-left"},{"label":"BMW workshop manual download","href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}],"tools":["Flashlight","Correct replacement bulb","Clean cloth","Helper for brake and reverse checks"],"cautions":["Park, set the parking brake and switch the lamps and ignition off before touching the holder.","Let the bulb cool. Avoid forcing the carrier or fitting a different wattage."],"steps":[{"title":"Identify the circuit that failed","body":"Compare the two sides with the parking lights, hazards and brake lamps operated separately. If testing the reverse lights, secure the car and have a helper observe with the engine off.","check":"You know which function and side have failed."},{"title":"Release the trunk-side cover","body":"Open the trunk and turn the fastener on the cover behind the affected lens. Lift out the cover and expose the bulb carrier. Compare the installed layout with the rear lamp diagram.","check":"The carrier is accessible without levering the exterior lens."},{"title":"Match and replace the bulb","body":"Remove the bulb from the affected socket. Match the wattage, base and contact arrangement to the original and the catalog. Check that the contacts and carrier are clean, dry and intact. Fit the matching bulb and refit the cover.","check":"The bulb seats securely and the cover fastens without force."},{"title":"Test every function on that side","body":"Switch the circuits on one at a time with a helper. If a lamp still fails or the carrier is damaged, check the matching wiring diagram and connector before replacing anything else.","check":"The repaired lamp, its neighboring lamps and any check-control warning behave normally."}],"jobSupport":{"reviewedOn":"2026-11-11","sourceSha256":"fa72b3321315a2f2a0f4df6d6879eae4ec7c639f8b0f6f41fd154adcb0a4f095","requiredParts":["Bulb with the wattage, base and contacts listed for the fitted lamp"],"conditionalParts":["Bulb carrier or gasket if the housing shows damage or water entry"],"stopConditions":["The socket is melted, heavily corroded or wet.","The replacement base or contacts differ from the fitted bulb."],"steps":[{"number":1,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":2,"tools":["Flashlight"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":3,"tools":["Matching bulb","Clean cloth"],"source":{"printed":"63-7","pdf":1192,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}},{"number":4,"tools":["Helper"],"source":{"printed":"00-16","pdf":23,"href":"https://www.allcarmanuals.com/factory-service-manual-343-BMW-3-Series-E30.html"}}]}}'::jsonb) on conflict do nothing;
