insert into public.guides(id,component_id,title,source_id,source_locator,engines,review_status,content) values ('e30-oil-service', 'engine', 'Plan an M20 oil and filter service', 'e30-factory-repair-upload', '00-15 · Engine oil service, operation 00 00 249', array['M20'], 'draft', '{"slug":"e30-oil-service","title":"Plan an M20 oil and filter service","system":"engine","engines":["M20"],"level":"Beginner","kind":"reference","duration":"15–25 min preparation","durationBasis":"Time to identify the fitted hardware and gather supplies. Drain and refill time varies.","summary":"Match the filter and drain hardware, then find the factory fill quantities and service checks.","reviewStatus":"draft","sourceChecked":true,"applicability":"US 325i / 325is M20 handbook figures. Identify the installed sump and filter, especially on a swapped engine.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"00-15 · Engine oil service, operation 00 00 249","pdfPages":[22]},"evidence":[{"label":"BMW 325i handbook · filling capacities, p. 84","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=85"},{"label":"BMW 1991 325i oil filter diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/lubrication_system_oil_filter.html"},{"label":"Oil filler location","href":"/quick-reference/locations?point=oil"}],"tools":["Drain pan","Correct filter tool and drain plug socket","Torque wrench","Funnel","Gloves and eye protection"],"cautions":["Use level ground for the final oil reading and rated supports if access requires lifting.","Avoid hot oil and confirm the drain plug tightening specification for the installed sump."],"steps":[{"title":"Identify the service parts","body":"Compare the installed filter, drain plug and seal with your catalog. Gather an approved oil in a viscosity suitable for the expected temperature.","check":"The filter and new seal match the installed parts."},{"title":"Check the handbook fill amount","body":"The 325i handbook lists 4.25 L with the filter changed, or 4.0 L without. Confirm the procedure for the installed sump and use the dipstick for the final level.","check":"You have enough oil and a way to verify the level."},{"title":"Plan the final checks","body":"After following the service procedure, check for leaks at the filter and drain plug. On level ground, allow oil to drain back and recheck the dipstick. Take used oil and the filter to an approved collection point.","check":"The level is in range and the filter and drain plug stay dry."}]}'::jsonb) on conflict(id) do nothing;
insert into public.guide_revision_archive(guide_id,revision,content) values ('e30-oil-service', '42328c6760979698cad1d056', '{"slug":"e30-oil-service","title":"Plan an M20 oil and filter service","system":"engine","engines":["M20"],"level":"Beginner","kind":"reference","duration":"15–25 min preparation","durationBasis":"Time to identify the fitted hardware and gather supplies. Drain and refill time varies.","summary":"Match the filter and drain hardware, then find the factory fill quantities and service checks.","reviewStatus":"draft","sourceChecked":true,"applicability":"US 325i / 325is M20 handbook figures. Identify the installed sump and filter, especially on a swapped engine.","source":{"id":"e30-factory-repair-upload","title":"BMW E30 Repair Manual","section":"00-15 · Engine oil service, operation 00 00 249","pdfPages":[22]},"evidence":[{"label":"BMW 325i handbook · filling capacities, p. 84","href":"https://www.billswebspace.com/BMW%20E30%20Owner%20Manual%20%28325i-325is%29.pdf#page=85"},{"label":"BMW 1991 325i oil filter diagram","href":"https://www.bmwpartsdeal.com/parts-list/1991-bmw-325i-coupe_e30/engine/lubrication_system_oil_filter.html"},{"label":"Oil filler location","href":"/quick-reference/locations?point=oil"}],"tools":["Drain pan","Correct filter tool and drain plug socket","Torque wrench","Funnel","Gloves and eye protection"],"cautions":["Use level ground for the final oil reading and rated supports if access requires lifting.","Avoid hot oil and confirm the drain plug tightening specification for the installed sump."],"steps":[{"title":"Identify the service parts","body":"Compare the installed filter, drain plug and seal with your catalog. Gather an approved oil in a viscosity suitable for the expected temperature.","check":"The filter and new seal match the installed parts."},{"title":"Check the handbook fill amount","body":"The 325i handbook lists 4.25 L with the filter changed, or 4.0 L without. Confirm the procedure for the installed sump and use the dipstick for the final level.","check":"You have enough oil and a way to verify the level."},{"title":"Plan the final checks","body":"After following the service procedure, check for leaks at the filter and drain plug. On level ground, allow oil to drain back and recheck the dipstick. Take used oil and the filter to an approved collection point.","check":"The level is in range and the filter and drain plug stay dry."}]}'::jsonb) on conflict do nothing;
